"use strict";

/* =====================================================================
   Het Kompas, aanleverplatform onderwijs.
   De browser toont alleen wat de server (Supabase-functie kompas2) voor deze gebruiker
   teruggeeft; elke wijziging wordt op de server opnieuw gecontroleerd.
   ===================================================================== */

const LOGO = `<img src="data:image/png;base64," alt="" width="34" height="34" style="display:block">`;
const WOORDMERK = `<img src="data:image/png;base64," alt="De Nieuwe Koers" class="auth-wordmark">`;

const MAX_BESTAND_MB = 20;
// De server draait in Supabase (eigen project, los van het-kompas.net). De sessie zit in een token per tabblad.
const API_ADRES = "https://mcjnsomdphjrmtqoapjg.supabase.co/functions/v1/kompas2";
let TOKEN = "";
try { TOKEN = sessionStorage.getItem("kompas_token") || ""; } catch (e) { /* privévenster */ }
function zetToken(t) {
    TOKEN = t || "";
    try { TOKEN ? sessionStorage.setItem("kompas_token", TOKEN) : sessionStorage.removeItem("kompas_token"); } catch (e) { /* */ }
}
let klaar = false;

const data = { scholen: {}, vakken: {}, leerlingen: {}, opdrachten: {}, opmerkingen: {}, bijlagen: {} };

let S = {
    rol: null,          // 'docent' | 'leerling' | 'admin'
    ik: null,           // {id, naam, schoolId}
    scherm: "login",
    tab: "leerling",
    param: null,
    melding: null,
    zojuist: null,
};

/* ---------------------------------------------------------------- hulp */
const el = document.getElementById("app");
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const lijst = (naam) => Object.values(data[naam]);
const vind = (naam, id) => data[naam][id] || null;
const nieuwId = () => {
    const a = new Uint8Array(8);
    crypto.getRandomValues(a);
    return [...a].map(x => x.toString(16).padStart(2, "0")).join("");
};

function isoWeek(d = new Date()) {
    const t = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    t.setUTCDate(t.getUTCDate() + 4 - (t.getUTCDay() || 7));
    const jan1 = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
    return { week: Math.ceil(((t - jan1) / 86400000 + 1) / 7), jaar: t.getUTCFullYear() };
}
const NU = isoWeek();

const MAANDEN = ["jan", "feb", "mrt", "apr", "mei", "jun", "jul", "aug", "sep", "okt", "nov", "dec"];
function datumKort(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d)) return "";
    return `${d.getDate()} ${MAANDEN[d.getMonth()]} ${d.getFullYear()}`;
}
const weeklabel = (w, j) => `Week ${w} · ${j}`;
function wekenInJaar(jaar) {
    const d = new Date(Date.UTC(jaar, 11, 28));
    return isoWeek(d).week;
}
function volgendeWeek(week, jaar) {
    return week >= wekenInJaar(jaar) ? { week: 1, jaar: jaar + 1 } : { week: week + 1, jaar };
}
/** Alle weken van 'van' t/m 'tot', met jaarwissel. */
function wekenReeks(van, tot, jaar, max = 26) {
    const reeks = [{ week: van, jaar }];
    if (!tot || tot === van) return reeks;
    let w = van, j = jaar;
    for (let i = 0; i < max - 1; i++) {
        ({ week: w, jaar: j } = volgendeWeek(w, j));
        reeks.push({ week: w, jaar: j });
        if (w === tot) break;
    }
    return reeks;
}
const vakkenVanSchool = (schoolId) => lijst("vakken").filter(v => v.schoolId === schoolId && v.actief).sort((a, b) => a.naam.localeCompare(b.naam));
const vakkenVanLeerling = (l) => (l.vakken || []).map(id => vind("vakken", id)).filter(v => v && v.actief).sort((a, b) => a.naam.localeCompare(b.naam));
function grootte(b) {
    if (!b) return "";
    if (b < 1024) return b + " B";
    if (b < 1048576) return Math.round(b / 1024) + " KB";
    return (b / 1048576).toFixed(1) + " MB";
}
function soortBestand(naam) {
    const e = (naam.split(".").pop() || "").toLowerCase();
    if (["jpg", "jpeg", "png", "gif", "webp", "heic"].includes(e)) return "afbeelding";
    if (e === "pdf") return "pdf";
    if (["doc", "docx", "odt", "rtf", "txt"].includes(e)) return "tekst";
    if (["xls", "xlsx", "csv"].includes(e)) return "tabel";
    if (["ppt", "pptx"].includes(e)) return "presentatie";
    if (["mp3", "m4a", "mp4"].includes(e)) return "media";
    return "bestand";
}
function initialen(naam) {
    const d = String(naam).trim().split(/\s+/);
    return ((d[0]?.[0] || "") + (d.length > 1 ? d[d.length - 1][0] : "")).toUpperCase();
}
function nieuweCode(prefix) {
    const a = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
    const d = (n) => Array.from({ length: n }, () => a[Math.floor(Math.random() * a.length)]).join("");
    return (prefix ? prefix.slice(0, 3).toUpperCase().replace(/[^A-Z]/g, "X") + "-" : "") + d(4) + "-" + d(4);
}
const normCode = (c) => String(c).toUpperCase().replace(/[^A-Z0-9-]/g, "");

function melden(tekst, soort = "ok") { S.melding = { tekst, soort }; teken(); }
function ga(scherm, param = null, anker = null) {
    if (scherm !== "docent-leerling") S.zojuist = null;
    S.scherm = scherm; S.param = param; teken();
    if (anker) {
        const doel = document.getElementById(anker);
        if (doel) return doel.scrollIntoView({ block: "start", behavior: "auto" });
    }
    window.scrollTo(0, 0);
}

/* ------------------------------------------------------------- opslag */
async function api(actie, body = null, opties = {}) {
    const init = { method: body ? "POST" : "GET", credentials: "omit", headers: { "X-Kompas-Token": TOKEN } };
    if (body instanceof FormData) init.body = body;
    else if (body) { init.headers["Content-Type"] = "application/json"; init.body = JSON.stringify(body); }
    let r;
    try { r = await fetch(API_ADRES + "?actie=" + encodeURIComponent(actie), init); }
    catch (e) { throw new Error("Geen verbinding met de server. Probeer het opnieuw."); }
    let antwoord = null;
    try { antwoord = await r.json(); } catch (e) { /* geen json */ }
    if (antwoord && typeof antwoord.token === "string" && (antwoord.token || actie === "uitloggen")) zetToken(antwoord.token);
    if (r.status === 401) zetToken("");
    if (r.status === 401 && !opties.stil) {
        S.rol = null; S.ik = null; S.scherm = "login";
        for (const c of Object.keys(data)) data[c] = {};
        teken();
        throw new Error(antwoord?.fout || "Je bent uitgelogd. Log opnieuw in.");
    }
    if (!r.ok) throw new Error(antwoord?.fout || "Er ging iets mis (" + r.status + ").");
    return antwoord || {};
}

async function laadStaat() {
    const s = await api("staat", null, { stil: true });
    if (!s.rol) zetToken("");
    S.rol = s.rol || null;
    S.ik = s.ik || null;
    for (const c of Object.keys(data)) data[c] = {};
    for (const [c, rijen] of Object.entries(s.data || {})) {
        if (!data[c]) continue;
        for (const r of rijen) data[c][r.id] = r;
    }
}

let bijwerkTimer = null;
function straksBijwerken() {
    clearTimeout(bijwerkTimer);
    bijwerkTimer = setTimeout(async () => { try { await laadStaat(); teken(); } catch (e) { /* stil */ } }, 400);
}

async function schrijf(collectie, id, body) {
    data[collectie][id] = { id, ...body };
    try { await api("opslaan", { collectie, id, body }); }
    catch (e) { melden(e.message || "Opslaan mislukte.", "fout"); }
    straksBijwerken();
}
async function wis(collectie, id) {
    delete data[collectie][id];
    try { await api("verwijderen", { collectie, id }); }
    catch (e) { melden(e.message || "Verwijderen mislukte.", "fout"); }
    straksBijwerken();
}

