function tekenDocentDashboard() {
    const leerlingen = lijst("leerlingen")
        .filter(l => l.schoolId === S.ik.schoolId && l.actief)
        .sort((a, b) => a.naam.localeCompare(b.naam));
    const school = vind("scholen", S.ik.schoolId);

    return `
    <div class="kop">
      <div>
        <h1>Mijn leerlingen</h1>
        <p class="zacht">${esc(school ? school.naam : "")} · ${weeklabel(NU.week, NU.jaar)}</p>
      </div>
    </div>
    ${leerlingen.length === 0 ? `<div class="leeg"><h3>Nog geen leerlingen gekoppeld</h3><p>De beheerder koppelt de leerlingen aan jouw school.</p></div>` : `
    <div class="raster">
      ${leerlingen.map(l => {
        const alle = lijst("opdrachten").filter(o => o.leerlingId === l.id);
        const week = alle.filter(o => o.werkweek === NU.week && o.jaar === NU.jaar).length;
        const nv = vakkenVanLeerling(l).length;
        const afWeek = alle.filter(o => o.werkweek === NU.week && o.jaar === NU.jaar && o.afgerond).length;
        return `<button class="kaart leerlingkaart" data-ga="docent-leerling" data-id="${l.id}">
            <span class="initialen">${esc(initialen(l.naam))}</span>
            <span class="naam">${esc(l.naam)}</span>
            ${l.klas ? `<span class="mini" style="display:block">Klas ${esc(l.klas)}</span>` : ""}
            <span class="mini" style="display:block">${week} opdracht${week === 1 ? "" : "en"} deze week · ${alle.length} in totaal</span>
            ${week ? `<span class="mini" style="display:block;color:${afWeek === week ? "var(--groen-600)" : "var(--grijs-700)"}">${afWeek} van ${week} afgerond</span>` : ""}
            ${nv === 0 ? `<span class="mini" style="display:block;color:var(--oker)">Nog geen vakken aangevinkt</span>` : ""}
          </button>`;
      }).join("")}
    </div>`}`;
}

function groepeerPerWeek(opdrachten) {
    const groepen = new Map();
    for (const o of opdrachten) {
        const s = `${o.jaar}|${o.werkweek}`;
        if (!groepen.has(s)) groepen.set(s, []);
        groepen.get(s).push(o);
    }
    return [...groepen.entries()].sort((a, b) => {
        const [ja, wa] = a[0].split("|").map(Number), [jb, wb] = b[0].split("|").map(Number);
        return jb - ja || wb - wa;
    });
}

function tekenDocentLeerling() {
    const l = vind("leerlingen", S.param);
    if (!l || l.schoolId !== S.ik.schoolId) return `<div class="leeg"><h3>Niet gevonden</h3><p>Deze leerling hoort niet bij jouw school.</p></div>`;
    const opdrachten = lijst("opdrachten").filter(o => o.leerlingId === l.id);

    return `
    <button class="terug" data-ga="docent-dashboard">← Alle leerlingen</button>
    <div class="kop">
      <div>
        <h1>${esc(l.naam)}</h1>
        <p class="zacht">${esc(vind("scholen", l.schoolId)?.naam || "")}${l.klas ? " · klas " + esc(l.klas) : ""}</p>
      </div>
    </div>
    ${l.notitie ? `<div class="melding let" style="margin-bottom:1.2rem"><strong>Aandachtspunt:</strong> ${esc(l.notitie)}</div>` : ""}

    ${(() => {
      const schoolvakken = vakkenVanSchool(l.schoolId);
      const eigen = vakkenVanLeerling(l);
      const ids = eigen.map(v => v.id);
      return `<details class="uitklap" ${eigen.length ? "" : "open"}>
        <summary>Vakken van ${esc(l.naam)}
          <span class="zacht">— ${eigen.length ? esc(eigen.map(v => v.naam).join(", ")) : "nog niets aangevinkt"}</span>
        </summary>
        <p class="mini">${schoolvakken.length
            ? "Vink aan welke vakken deze leerling volgt. Alleen die vakken kun je bij een opdracht kiezen."
            : `Voor ${esc(vind("scholen", l.schoolId)?.naam || "deze school")} staan nog geen vakken klaar. Voeg hieronder zelf een vak toe.`}</p>
          <form class="formulier" data-form="vakken-leerling" data-id="${l.id}">
            <div class="vakkenkiezer">
              ${schoolvakken.map(v => `<label class="vakvinkje">
                <input type="checkbox" name="vakken" value="${v.id}" ${ids.includes(v.id) ? "checked" : ""}>
                <span>${esc(v.naam)}</span>
              </label>`).join("")}
            </div>
            <label class="mini">Staat het vak er niet tussen? Typ het hier, dan wordt het toegevoegd en aangevinkt.
              <input type="text" name="nieuwVak" maxlength="100" placeholder="Bijvoorbeeld: CKV, of meerdere met een komma">
            </label>
            <div><button class="knop klein" type="submit">Vakken opslaan</button></div>
          </form>
      </details>`;
    })()}
    ${(() => {
      const vakken = vakkenVanLeerling(l);
      const ids = vakken.map(v => v.id);
      const overig = opdrachten.filter(o => !ids.includes(o.vakId));
      const tegels = vakken.map(v => ({ id: v.id, naam: v.naam, rijen: opdrachten.filter(o => o.vakId === v.id) }));
      if (overig.length) tegels.push({ id: "__overig", naam: "Overig", rijen: overig });
      if (!tegels.length) return `<div class="leeg"><h3>Nog geen vakken</h3>
        <p>Vink hierboven eerst de vakken van ${esc(l.naam)} aan. Daarna kun je per vak werk klaarzetten.</p></div>`;

      const keuze = S.gekozenVak && S.gekozenVak.leerlingId === l.id ? S.gekozenVak.vakId : null;
      const gekozen = tegels.find(t => t.id === keuze) || null;
      const ditWeek = (o) => o.werkweek === NU.week && o.jaar === NU.jaar;

      const tegelHtml = tegels.map(t => {
        const nu = t.rijen.filter(ditWeek);
        const nuAf = nu.filter(o => o.afgerond).length;
        const status = nu.length === 0 ? `<span class="merkje dicht">niets deze week</span>`
          : `<span class="merkje ${nuAf === nu.length ? "af" : "open"}">deze week ${nuAf}/${nu.length} af</span>`;
        return `<button class="vaktegel ${t.id === keuze ? "gekozen" : ""}" data-actie="docent-vak" data-id="${l.id}" data-vak="${t.id}" aria-pressed="${t.id === keuze}">
          <b>${esc(t.naam)}</b>
          <span class="mini">${t.rijen.length} opdracht${t.rijen.length === 1 ? "" : "en"}</span>
          ${status}
        </button>`;
      }).join("");

      let detail;
      if (!gekozen) {
        detail = `<div class="leeg"><h3>Kies een vak</h3><p>Klik op een vak om het werk van ${esc(l.naam)} voor dat vak te zien en nieuw werk klaar te zetten.</p></div>`;
      } else {
        const rijen = [...gekozen.rijen].sort((a, b) => b.jaar - a.jaar || b.werkweek - a.werkweek);
        detail = `<div class="vakdetail" id="vakdetail">
          <div class="kop" style="margin-bottom:.9rem">
            <div><h2 style="margin:0">${esc(gekozen.naam)}</h2></div>
            ${gekozen.id === "__overig" ? "" : `<button class="knop" data-actie="nieuw-voor-vak" data-id="${l.id}" data-vak="${gekozen.id}">+ Opdracht voor ${esc(gekozen.naam)}</button>`}
          </div>
          ${rijen.length === 0 ? `<div class="leeg"><p>Voor ${esc(gekozen.naam)} is nog niets klaargezet.</p></div>` : `
          <div class="opdrachtlijst">
            ${rijen.map(o => {
              const nb = lijst("bijlagen").filter(x => x.opdrachtId === o.id).length;
              const nm = lijst("opmerkingen").filter(m => m.opdrachtId === o.id).length;
              const zojuist = S.zojuist === o.id;
              const kop = o.titel && o.titel !== o.vak && gekozen.id !== "__overig" ? o.titel : "";
              return `<button class="opdrachtrij ${o.afgerond ? "af" : (o.zichtbaar ? "open" : "dicht")} ${zojuist ? "zojuist" : ""}" data-ga="docent-opdracht" data-id="${o.id}">
                <span class="weekbol ${ditWeek(o) ? "nu" : ""}"><small>week</small>${o.werkweek}</span>
                <span class="body">
                  <span class="titel" style="display:block">${esc(kop || (gekozen.id === "__overig" ? o.titel : "") || (o.omschrijving || "").split("\n")[0] || "Geen omschrijving")}</span>
                  <span class="meta">${[o.jaar !== NU.jaar ? String(o.jaar) : null, ditWeek(o) ? "deze week" : null, nb ? `${nb} bijlage${nb === 1 ? "" : "n"}` : null, nm ? `${nm} opmerking${nm === 1 ? "" : "en"}` : null, o.afgerond ? `afgerond op ${datumKort(o.afgerondOp)}` : null, o.gekopieerdVan ? "doorgezet" : null].filter(Boolean).join(" · ") || "&nbsp;"}</span>
                </span>
                <span class="merkje ${zojuist ? "nieuw" : (o.afgerond ? "af" : (o.zichtbaar ? "open" : "dicht"))}">${zojuist ? "Zojuist klaargezet" : (o.afgerond ? "✓ Afgerond" : (o.zichtbaar ? "Zichtbaar" : "Nog dicht"))}</span>
              </button>`;
            }).join("")}
          </div>`}
        </div>`;
      }
      return `<div class="vaktegels">${tegelHtml}</div>${detail}`;
    })()}`;
}
function tekenOpdrachtFormulier() {
    const bewerken = S.scherm === "docent-bewerk";
    const p = S.param;
    const voorkeur = (p && typeof p === "object") ? p : null;
    const o = bewerken ? vind("opdrachten", p) : null;
    const l = bewerken ? vind("leerlingen", o.leerlingId) : vind("leerlingen", voorkeur ? voorkeur.id : p);
    if (!l) return `<div class="leeg"><h3>Niet gevonden</h3></div>`;
    const bijlagen = bewerken ? lijst("bijlagen").filter(b => b.opdrachtId === o.id) : [];

    return `
    <button class="terug" data-ga="${bewerken ? "docent-opdracht" : "docent-leerling"}" data-id="${bewerken ? o.id : l.id}">← Terug</button>
    <div class="kop">
      <div>
        <h1>${bewerken ? "Opdracht bewerken" : "Werk aanleveren"}</h1>
        <p class="zacht">Voor ${esc(l.naam)}</p>
      </div>
    </div>

    <form class="kaart formulier" data-form="opdracht" data-id="${bewerken ? o.id : ""}" data-leerling="${l.id}">
      ${(() => {
        const eigen = vakkenVanLeerling(l);
        const huidig = o?.vakId || voorkeur?.vakId || "";
        return `<div><label>Vak</label>
          ${eigen.length ? "" : `<p class="mini">Voor ${esc(l.naam)} zijn nog geen vakken aangevinkt. Typ hieronder het vak.</p>`}
          <div class="vakkenkiezer" style="margin-top:.35rem">
            ${eigen.map(v => `<label class="vakvinkje"><input type="radio" name="vakId" value="${v.id}" required ${huidig === v.id ? "checked" : ""}><span>${esc(v.naam)}</span></label>`).join("")}
            <label class="vakvinkje"><input type="radio" name="vakId" value="__nieuw" required ${eigen.length ? "" : "checked"}><span>+ Ander vak</span></label>
          </div>
          <label class="mini nieuwvak" style="margin-top:.5rem">Naam van het vak
            <input type="text" name="nieuwVak" maxlength="100" placeholder="Bijvoorbeeld: CKV">
          </label></div>`;
      })()}
      <div class="rij">
        <label>Week<input type="number" name="werkweek" min="1" max="53" required value="${o?.werkweek ?? voorkeur?.week ?? NU.week}"></label>
        ${bewerken ? "" : `<label>Tot en met week <span class="zacht">(mag leeg)</span>
          <input type="number" name="totWeek" min="1" max="53" placeholder="alleen deze week"></label>`}
        <label>Jaar<input type="number" name="jaar" min="2020" max="2100" required value="${o?.jaar ?? voorkeur?.jaar ?? NU.jaar}"></label>
      </div>
      <label>Wat moet de leerling doen?
        <textarea name="omschrijving" placeholder="Schrijf in korte, duidelijke stappen op wat de leerling moet doen. Bijvoorbeeld: lees blz. 42 t/m 51, maak daarna opdracht 1 tot en met 4.">${esc(o?.omschrijving || "")}</textarea>
      </label>
      <label>Link <span class="zacht">(mag leeg)</span>
        <input type="text" name="link" placeholder="www.voorbeeld.nl/oefenen" value="${esc(o?.link || "")}">
      </label>
      <label>Bestanden toevoegen <span class="zacht">(meerdere tegelijk mag)</span>
        <input type="file" name="bijlagen" multiple>
      </label>
      <p class="mini">Maximaal ${MAX_BESTAND_MB} MB per bestand: PDF, Word, Excel, PowerPoint, afbeeldingen, geluid of video.</p>

      ${bijlagen.length ? `<div>
        <h3>Bestanden die al bij deze opdracht staan</h3>
        <div class="bijlagen">
          ${bijlagen.map(b => `<div class="bijlage" style="cursor:default">
            <span class="type">${soortBestand(b.naam)}</span>
            <span class="naam">${esc(b.naam)}</span>
            <span class="mini">${grootte(b.omvang)}</span>
            <button type="button" class="knop klein gevaar" data-actie="bijlage-weg" data-id="${b.id}">Verwijderen</button>
          </div>`).join("")}
        </div>
      </div>` : ""}

      <label class="vinkje">
        <input type="checkbox" name="zichtbaar" ${(!bewerken || o.zichtbaar) ? "checked" : ""}>
        <span>Meteen zichtbaar maken voor de leerling <span class="zacht">(anders zet de beheerder de opdracht later open)</span></span>
      </label>

      <div class="knoppenrij">
        <button class="knop" type="submit">${bewerken ? "Wijzigingen opslaan" : "Opdracht klaarzetten"}</button>
        <button type="button" class="knop rand" data-ga="${bewerken ? "docent-opdracht" : "docent-leerling"}" data-id="${bewerken ? o.id : l.id}">Annuleren</button>
      </div>
    </form>`;
}

function tekenDocentOpdracht() {
    const o = vind("opdrachten", S.param);
    if (!o) return `<div class="leeg"><h3>Niet gevonden</h3></div>`;
    const l = vind("leerlingen", o.leerlingId);
    const bijlagen = lijst("bijlagen").filter(b => b.opdrachtId === o.id);
    const opmerkingen = lijst("opmerkingen").filter(m => m.opdrachtId === o.id).sort((a, b) => (b.aangemaakt || "").localeCompare(a.aangemaakt || ""));

    return `
    <button class="terug" data-ga="docent-leerling" data-id="${l.id}">← ${esc(l.naam)}</button>
    <div class="kop">
      <div>
        <h1>${esc(o.titel)}</h1>
        <p class="zacht">${weeklabel(o.werkweek, o.jaar)}${o.vak ? " · " + esc(o.vak) : ""} · aangeleverd door ${esc(vind("scholen", o.schoolId)?.naam || "de school")} op ${datumKort(o.aangemaakt)}</p>
      </div>
      <div class="knoppenrij">
        ${o.afgerond ? `<span class="merkje af">✓ Afgerond op ${datumKort(o.afgerondOp)}</span>` : ""}
        <span class="merkje ${o.zichtbaar ? "open" : "dicht"}">${o.zichtbaar ? "Zichtbaar voor leerling" : "Nog niet zichtbaar"}</span>
        <button class="knop rand" data-ga="docent-bewerk" data-id="${o.id}">Bewerken</button>
      </div>
    </div>

    <div class="raster-2">
      <div class="kolom">
        <div class="kaart">
          <h3>Wat de leerling moet doen</h3>
          ${o.omschrijving?.trim() ? `<div class="tekstblok">${esc(o.omschrijving)}</div>` : `<p class="zacht">Er is nog geen omschrijving ingevuld.</p>`}
          ${o.link ? `<p style="margin:1rem 0 0"><a class="knop klein rand" href="${esc(o.link)}" target="_blank" rel="noopener">Link openen ↗</a></p>` : ""}
        </div>

        ${bijlagen.length ? `<div>
          <h2 style="margin-top:.6rem">Bijlagen</h2>
          <div class="bijlagen">
            ${bijlagen.map(b => `<button class="bijlage" data-actie="bijlage-open" data-id="${b.id}">
              <span class="type">${soortBestand(b.naam)}</span>
              <span class="naam">${esc(b.naam)}</span>
              <span class="mini">${grootte(b.omvang)}</span>
            </button>`).join("")}
          </div>
        </div>` : ""}

        <div>
          <h2 style="margin-top:.6rem">Opmerkingen bij dit werk</h2>
          <div class="kaart">
            <form class="formulier" data-form="opmerking" data-id="${o.id}">
              <label>Nieuwe opmerking
                <textarea name="tekst" style="min-height:88px" placeholder="Bijvoorbeeld: eerste twee opdrachten af, rest volgt volgende week."></textarea>
              </label>
              <label>Je naam <span class="zacht">(mag leeg, dan komt de school erbij te staan)</span>
                <input type="text" name="auteur" maxlength="120" placeholder="Bijvoorbeeld: Marieke">
              </label>
              <div><button class="knop klein" type="submit">Opmerking plaatsen</button></div>
            </form>
            ${opmerkingen.length ? `<ul class="lijst-plat" style="margin-top:1.1rem">
              ${opmerkingen.map(m => `<li><strong>${esc(m.auteur)}</strong> <span class="mini">· ${datumKort(m.aangemaakt)}</span>
                <div class="tekstblok">${esc(m.tekst)}</div></li>`).join("")}
            </ul>` : `<p class="mini" style="margin-top:1rem">Nog geen opmerkingen. Opmerkingen zijn alleen zichtbaar voor docenten en beheer.</p>`}
          </div>
        </div>
      </div>

      <div class="kolom">
        <div class="kaart">
          <h3>Gegevens</h3>
          <ul class="lijst-plat">
            <li>Leerling: <strong>${esc(l.naam)}</strong></li>
            <li>Vak: <strong>${esc(o.vak || "—")}</strong></li>
            <li>Week: <strong class="tab-nums">${o.werkweek}</strong> (${o.jaar})</li>
            <li>Bijlagen: <strong>${bijlagen.length}</strong></li>
            <li>Status: <strong>${o.afgerond ? `afgerond op ${datumKort(o.afgerondOp)}` : "nog niet afgerond"}</strong></li>
            <li>Aangemaakt: ${datumKort(o.aangemaakt)}</li>
            ${o.gewijzigd ? `<li>Bijgewerkt: ${datumKort(o.gewijzigd)}</li>` : ""}
            ${o.gekopieerdVan ? `<li class="mini">Doorgezet uit een eerdere week</li>` : ""}
          </ul>
        </div>
        <div class="kaart">
          <h3>Ook volgende week</h3>
          <p class="mini">Zet dezelfde opdracht, met bijlagen, opnieuw klaar in ${weeklabel(volgendeWeek(o.werkweek, o.jaar).week, volgendeWeek(o.werkweek, o.jaar).jaar)}.</p>
          <button class="knop klein rand" data-actie="opdracht-kopie" data-id="${o.id}">Doorzetten naar week ${volgendeWeek(o.werkweek, o.jaar).week}</button>
        </div>
        <div class="kaart">
          <h3>Opdracht verwijderen</h3>
          <p class="mini">De opdracht en de bijlagen worden dan definitief verwijderd.</p>
          <button class="knop klein gevaar" data-actie="opdracht-weg" data-id="${o.id}">Verwijderen</button>
        </div>
      </div>
    </div>`;
}

function tekenLeerlingDashboard() {
    const opdrachten = lijst("opdrachten").filter(o => o.leerlingId === S.ik.id && o.zichtbaar);
    return `
    <div class="kop">
      <div>
        <h1>Hoi ${esc(S.ik.naam.split(" ")[0])}</h1>
        <p class="zacht">Dit is het werk dat voor je klaarstaat.</p>
      </div>
    </div>
    ${opdrachten.length === 0 ? `<div class="leeg"><h3>Er staat nog niets voor je klaar</h3><p>Zodra je docent werk klaarzet, zie je het hier.</p></div>` :
      groepeerPerWeek(opdrachten).map(([s, groep]) => {
        const [jaar, week] = s.split("|").map(Number);
        const nu = week === NU.week && jaar === NU.jaar;
        return `<div class="weekkop"><span>${weeklabel(week, jaar)}${nu ? " <em>— deze week</em>" : ""}</span><span class="weeklijn"></span></div>
          <div class="opdrachtlijst">
            ${groep.map(o => {
              const nb = lijst("bijlagen").filter(b => b.opdrachtId === o.id).length;
              return `<button class="opdrachtrij ${o.afgerond ? "af" : "open"}" data-ga="leerling-opdracht" data-id="${o.id}">
                <span class="body">
                  <span class="titel" style="display:block">${esc(o.titel)}</span>
                  <span class="meta">${o.vak ? esc(o.vak) + " · " : ""}van ${esc(vind("scholen", o.schoolId)?.naam || "je school")}${nb ? ` · ${nb} bijlage${nb === 1 ? "" : "n"}` : ""}</span>
                </span>
                <span class="merkje ${o.afgerond ? "af" : "vak"}">${o.afgerond ? "✓ Afgerond" : "Bekijken →"}</span>
              </button>`;
            }).join("")}
          </div>`;
      }).join("")}`;
}

function tekenLeerlingOpdracht() {
    const o = vind("opdrachten", S.param);
    if (!o || o.leerlingId !== S.ik.id || !o.zichtbaar) {
        return `<div class="leeg"><h3>Deze opdracht staat niet voor je klaar</h3><p>Vraag je begeleider erna.</p>
                <button class="knop rand" data-ga="leerling-dashboard">Terug</button></div>`;
    }
    const bijlagen = lijst("bijlagen").filter(b => b.opdrachtId === o.id);
    return `
    <button class="terug" data-ga="leerling-dashboard">← Mijn opdrachten</button>
    <div class="kop">
      <div>
        <h1>${esc(o.titel)}</h1>
        <p class="zacht">${weeklabel(o.werkweek, o.jaar)}${o.vak ? " · " + esc(o.vak) : ""} · van ${esc(vind("scholen", o.schoolId)?.naam || "je school")}</p>
      </div>
    </div>
    ${o.afgerond ? `<div class="melding" style="margin-bottom:1.2rem">Deze opdracht staat op afgerond.</div>` : ""}
    <div class="kaart">
      <h3>Wat moet je doen?</h3>
      ${o.omschrijving?.trim() ? `<div class="tekstblok">${esc(o.omschrijving)}</div>` : `<p class="zacht">Je docent heeft hier nog geen uitleg bij gezet.</p>`}
      ${o.link ? `<p style="margin:1.2rem 0 0"><a class="knop groen" href="${esc(o.link)}" target="_blank" rel="noopener">Open de link ↗</a></p>` : ""}
    </div>
    ${bijlagen.length ? `<h2>Bestanden bij deze opdracht</h2>
      <div class="bijlagen">
        ${bijlagen.map(b => `<button class="bijlage" data-actie="bijlage-open" data-id="${b.id}">
          <span class="type">${soortBestand(b.naam)}</span>
          <span class="naam">${esc(b.naam)}</span>
          <span class="mini">${grootte(b.omvang)}</span>
        </button>`).join("")}
      </div>` : ""}
    <p class="mini" style="margin-top:1.6rem">Je hoeft hier niets in te leveren of af te vinken. Klaar met de opdracht? Laat het je begeleider weten.</p>`;
}

function tekenAdminDashboard() {
    const leerlingen = lijst("leerlingen").filter(l => l.actief);
    const dezeWeek = lijst("opdrachten").filter(o => o.werkweek === NU.week && o.jaar === NU.jaar);
    const af = dezeWeek.filter(o => o.afgerond).length;
    const dicht = dezeWeek.filter(o => !o.zichtbaar).length;
    const zonder = leerlingen.filter(l => !dezeWeek.some(o => o.leerlingId === l.id)).length;

    return `
    <div class="kop"><div>
      <h1>Overzicht</h1>
      <p class="zacht">${weeklabel(NU.week, NU.jaar)}</p>
    </div></div>

    <div class="statrij">
      <div class="stat"><b>${dezeWeek.length}</b><span>Opdrachten deze week</span></div>
      <div class="stat af"><b>${af}</b><span>Afgerond</span></div>
      <div class="stat ${dicht ? "let" : ""}"><b>${dicht}</b><span>Nog niet opengezet</span></div>
      <div class="stat ${zonder ? "let" : ""}"><b>${zonder}</b><span>Leerlingen zonder werk</span></div>
    </div>

    <div class="snelkeuze">
      <button class="snelknop hoofd" data-ga="admin-agenda"><b>Weekagenda</b><span>Rooster per leerling bekijken en afvinken</span></button>
      <button class="snelknop" data-ga="admin-opdrachten"><b>Opdrachten</b><span>Openzetten, afronden en doorzetten</span></button>
      <button class="snelknop" data-ga="admin-leerlingen"><b>Leerlingen</b><span>${leerlingen.length} actief, koppelcodes</span></button>
      <button class="snelknop" data-ga="admin-scholen"><b>Scholen</b><span>${lijst("scholen").filter(x => x.actief).length} scholen, docentcodes</span></button>
    </div>`;
}

function vorigeWeek(week, jaar) {
    return week <= 1 ? { week: wekenInJaar(jaar - 1), jaar: jaar - 1 } : { week: week - 1, jaar };
}

function tekenAdminAgenda() {
    const f = { week: NU.week, jaar: NU.jaar, schoolId: "", ...(S.param || {}) };
    const week = Number(f.week), jaar = Number(f.jaar);
    const vorige = vorigeWeek(week, jaar), volgende = volgendeWeek(week, jaar);
    const scholen = lijst("scholen").filter(s => s.actief).sort((a, b) => a.naam.localeCompare(b.naam));
    const leerlingen = lijst("leerlingen")
        .filter(l => l.actief && (!f.schoolId || l.schoolId === f.schoolId))
        .sort((a, b) => a.naam.localeCompare(b.naam));
    const vanWeek = lijst("opdrachten").filter(o => o.werkweek === week && o.jaar === jaar);

    const metOpdracht = [], zonder = [];
    for (const l of leerlingen) (vanWeek.some(o => o.leerlingId === l.id) ? metOpdracht : zonder).push(l);

    const totaal = vanWeek.filter(o => leerlingen.some(l => l.id === o.leerlingId));
    const af = totaal.filter(o => o.afgerond).length;
    const dicht = totaal.filter(o => !o.zichtbaar).length;
    const isNu = week === NU.week && jaar === NU.jaar;
    const gekozen = leerlingen.find(l => l.id === f.leerlingId) || null;
    const gekozenId = gekozen?.id || null;

    const kaart = (l) => {
        const eigen = vanWeek.filter(o => o.leerlingId === l.id);
        const klaar = eigen.filter(o => o.afgerond).length;
        const pct = eigen.length ? Math.round(klaar / eigen.length * 100) : 0;
        // Volgorde: eerst de vakken van de leerling (zoals in het weekschema), dan opdrachten zonder vak.
        const vakken = vakkenVanLeerling(l);
        const rijen = [];
        const gebruikt = new Set();
        for (const v of vakken) {
            const bij = eigen.filter(o => o.vakId === v.id);
            bij.forEach(o => gebruikt.add(o.id));
            if (bij.length) bij.forEach(o => rijen.push({ vak: v.naam, o }));
            else rijen.push({ vak: v.naam, o: null });
        }
        eigen.filter(o => !gebruikt.has(o.id))
            .sort((a, b) => (a.vak || "").localeCompare(b.vak || ""))
            .forEach(o => rijen.push({ vak: o.vak || "Overig", o }));

        return `<article class="agendakaart">
          <header>
            <div class="initialen">${esc(initialen(l.naam))}</div>
            <div>
              <div class="naam">${esc(l.naam)}</div>
              <div class="mini">${l.klas ? "Klas " + esc(l.klas) + " · " : ""}${esc(vind("scholen", l.schoolId)?.naam || "—")}</div>
            </div>
            <div class="voortgang">${klaar} van ${eigen.length} afgerond
              <div class="voortgangsbalk"><i style="width:${pct}%"></i></div></div>
          </header>
          ${rijen.map(({ vak, o }) => o ? `
          <div class="agendarij ${o.afgerond ? "klaar" : ""}">
            <div class="vaknaam">${esc(vak)}</div>
            <div class="wat">
              ${o.titel && o.titel !== o.vak ? `<strong>${esc(o.titel)}</strong>` : ""}
              ${o.omschrijving?.trim() ? `<div class="uitleg ${o.titel && o.titel !== o.vak ? "" : "hoofd"}">${esc(o.omschrijving.trim())}</div>`
                : (o.titel && o.titel !== o.vak ? "" : `<div class="uitleg">Geen omschrijving ingevuld.</div>`)}
              <div class="tags">
                <span class="merkje ${o.afgerond ? "af" : (o.zichtbaar ? "open" : "dicht")}">${o.afgerond ? "Afgerond " + datumKort(o.afgerondOp) : (o.zichtbaar ? "Open" : "Dicht")}</span>
                ${lijst("bijlagen").some(b => b.opdrachtId === o.id) ? `<span class="merkje">bijlage</span>` : ""}
                ${o.gekopieerdVan ? `<span class="merkje">doorgezet</span>` : ""}
              </div>
            </div>
            <div class="acties">
              <button class="knop klein ${o.afgerond ? "rand" : "af"}" data-actie="opdracht-afronden" data-id="${o.id}">${o.afgerond ? "Terugzetten" : "Afvinken"}</button>
              ${o.zichtbaar ? "" : `<button class="knop klein groen" data-actie="opdracht-wissel" data-id="${o.id}">Openzetten</button>`}
            </div>
          </div>` : `
          <div class="agendarij leeg">
            <div class="vaknaam">${esc(vak)}</div>
            <div class="wat">niets klaargezet</div>
            <div></div>
          </div>`).join("")}
        </article>`;
    };

    return `
    <div class="kop">
      <div>
        <h1>Weekagenda</h1>
        <p class="zacht">Per leerling wat er deze week gemaakt moet worden, per vak.</p>
      </div>
      <div class="agendabalk">
        ${scholen.length > 1 ? `<select data-actie="agenda-school" aria-label="School">
          <option value="">Alle scholen</option>
          ${scholen.map(s => `<option value="${s.id}" ${s.id === f.schoolId ? "selected" : ""}>${esc(s.naam)}</option>`).join("")}
        </select>` : ""}
        <button class="knop klein rand" data-actie="agenda-week" data-week="${vorige.week}" data-jaar="${vorige.jaar}" aria-label="Vorige week">‹</button>
        <span class="weeknaam">${weeklabel(week, jaar)}</span>
        <button class="knop klein rand" data-actie="agenda-week" data-week="${volgende.week}" data-jaar="${volgende.jaar}" aria-label="Volgende week">›</button>
        ${isNu ? "" : `<button class="knop klein" data-actie="agenda-week" data-week="${NU.week}" data-jaar="${NU.jaar}">Deze week</button>`}
      </div>
    </div>

    <div class="statrij">
      <div class="stat"><b>${metOpdracht.length}</b><span>Leerlingen met werk</span></div>
      <div class="stat"><b>${totaal.length}</b><span>Opdrachten deze week</span></div>
      <div class="stat af"><b>${af}</b><span>Afgerond</span></div>
      <div class="stat ${dicht ? "let" : ""}"><b>${dicht}</b><span>Nog niet opengezet</span></div>
    </div>

    ${leerlingen.length === 0 ? `<div class="leeg"><h3>Geen leerlingen</h3><p>Er zijn nog geen actieve leerlingen${f.schoolId ? " bij deze school" : ""}.</p></div>` : `
    <div class="agendakeuze">
      <div class="leerlingkiezer" role="list">
        <div class="mini kiezerkop">Kies een leerling</div>
        ${leerlingen.map(l => {
            const eigen = vanWeek.filter(o => o.leerlingId === l.id);
            const klaar = eigen.filter(o => o.afgerond).length;
            const gekozen = l.id === gekozenId;
            return `<button class="kiesrij ${gekozen ? "gekozen" : ""}" role="listitem" data-actie="agenda-kies" data-id="${l.id}" aria-pressed="${gekozen}">
              <span class="vinkje" aria-hidden="true">${gekozen ? "✓" : ""}</span>
              <span class="kiesnaam"><b>${esc(l.naam)}</b><small>${l.klas ? "Klas " + esc(l.klas) + " · " : ""}${esc(vind("scholen", l.schoolId)?.naam || "—")}</small></span>
              ${eigen.length
                ? `<span class="merkje ${klaar === eigen.length ? "af" : "open"}">${klaar}/${eigen.length}</span>`
                : `<span class="merkje dicht">niets</span>`}
            </button>`;
        }).join("")}
      </div>
      <div class="roosterpaneel">
        ${gekozen
          ? (vanWeek.some(o => o.leerlingId === gekozen.id)
              ? kaart(gekozen)
              : `<div class="leeg"><h3>${esc(gekozen.naam)}</h3><p>Voor ${weeklabel(week, jaar).toLowerCase()} is nog niets klaargezet.</p></div>`)
          : `<div class="leeg"><h3>Kies een leerling</h3><p>Klik links op een naam om het rooster van ${weeklabel(week, jaar).toLowerCase()} te zien.</p></div>`}
      </div>
    </div>`}`;
}

function tekenAdminScholen() {
    const scholen = lijst("scholen").sort((a, b) => a.naam.localeCompare(b.naam));
    return `
    <div class="kop"><div>
      <h1>Scholen en docentcodes</h1>
      <p class="zacht">Eén koppelcode per school. Alle docenten van die school gebruiken dezelfde code.</p>
    </div></div>
    <details class="uitklap">
      <summary>+ School toevoegen</summary>
      <form class="formulier" data-form="school-nieuw">
        <div class="rij">
          <label>Naam van de school<input type="text" name="naam" required maxlength="150" placeholder="Naam van de school"></label>
          <label>Plaats<input type="text" name="plaats" maxlength="100" placeholder="Plaats"></label>
        </div>
        <div><button class="knop" type="submit">School toevoegen</button></div>
      </form>
    </details>
    <div class="tabel-omhulsel"><table class="tabel">
      <thead><tr><th>School</th><th>Docentcode</th><th>Vakken</th><th>Leerlingen</th><th>Status</th><th></th></tr></thead>
      <tbody>
        ${scholen.map(s => `<tr class="${s.actief ? "" : "uit"}">
          <td><strong>${esc(s.naam)}</strong>${s.plaats ? `<div class="mini">${esc(s.plaats)}</div>` : ""}</td>
          <td><code class="code">${esc(s.koppelcode)}</code></td>
          <td class="tab-nums">${vakkenVanSchool(s.id).length}</td>
          <td class="tab-nums">${lijst("leerlingen").filter(l => l.schoolId === s.id && l.actief).length}</td>
          <td><span class="merkje ${s.actief ? "open" : "dicht"}">${s.actief ? "Actief" : "Ingetrokken"}</span></td>
          <td><div class="knoppenrij">
            <button class="knop klein rand" data-actie="school-code" data-id="${s.id}">Nieuwe code</button>
            <button class="knop klein ${s.actief ? "gevaar" : "rand"}" data-actie="school-wissel" data-id="${s.id}">${s.actief ? "Intrekken" : "Weer activeren"}</button>
          </div></td>
        </tr>`).join("") || `<tr><td colspan="6" class="zacht">Nog geen scholen toegevoegd.</td></tr>`}
      </tbody>
    </table></div>`;
}

function tekenAdminVakken() {
    const scholen = lijst("scholen").sort((a, b) => a.naam.localeCompare(b.naam));
    if (!scholen.length) {
        return `<div class="kop"><div><h1>Vakken per school</h1></div></div>
          <div class="leeg"><h3>Nog geen scholen</h3><p>Voeg eerst een school toe.</p>
          <button class="knop" data-ga="admin-scholen">Naar scholen</button></div>`;
    }
    const schoolId = (S.param && vind("scholen", S.param)) ? S.param : scholen[0].id;
    const vakken = lijst("vakken").filter(v => v.schoolId === schoolId).sort((a, b) => a.naam.localeCompare(b.naam));
    const school = vind("scholen", schoolId);

    return `
    <div class="kop">
      <div>
        <h1>Vakken per school</h1>
        <p class="zacht">Docenten kiezen uit deze lijst. Per leerling vinken zij aan welke vakken gelden.</p>
      </div>
      ${scholen.length > 1 ? `<label class="mini">School
        <select data-actie="kies-school">
          ${scholen.map(x => `<option value="${x.id}" ${x.id === schoolId ? "selected" : ""}>${esc(x.naam)}</option>`).join("")}
        </select></label>` : ""}
    </div>

    <details class="uitklap" ${vakken.length ? "" : "open"}>
      <summary>+ Vakken toevoegen aan ${esc(school.naam)}</summary>
      <form class="formulier" data-form="vak-nieuw" data-school="${schoolId}">
        <label>Vak of vakken
          <textarea name="naam" style="min-height:92px" placeholder="Nederlands, Rekenen, Engels&#10;of elk vak op een eigen regel"></textarea>
        </label>
        <p class="mini">Meerdere tegelijk mag: gescheiden door een komma of elk vak op een eigen regel.</p>
        <div><button class="knop" type="submit">Toevoegen</button></div>
      </form>
    </details>

    <div class="tabel-omhulsel"><table class="tabel">
      <thead><tr><th>Vak</th><th>Leerlingen</th><th>Opdrachten</th><th>Status</th><th></th></tr></thead>
      <tbody>
        ${vakken.map(v => `<tr class="${v.actief ? "" : "uit"}">
          <td>
            <form class="knoppenrij" data-form="vak-hernoem" data-id="${v.id}" style="gap:.4rem">
              <input type="text" name="naam" value="${esc(v.naam)}" maxlength="100" style="max-width:210px">
              <button class="knop klein rand" type="submit">Opslaan</button>
            </form>
          </td>
          <td class="tab-nums">${lijst("leerlingen").filter(l => (l.vakken || []).includes(v.id)).length}</td>
          <td class="tab-nums">${lijst("opdrachten").filter(o => o.vakId === v.id).length}</td>
          <td><span class="merkje ${v.actief ? "open" : "dicht"}">${v.actief ? "Actief" : "Uit"}</span></td>
          <td><button class="knop klein ${v.actief ? "gevaar" : "rand"}" data-actie="vak-wissel" data-id="${v.id}">${v.actief ? "Uitzetten" : "Weer aanzetten"}</button></td>
        </tr>`).join("") || `<tr><td colspan="5" class="zacht">Voor deze school staan nog geen vakken klaar.</td></tr>`}
      </tbody>
    </table></div>
    <p class="mini" style="margin-top:.8rem">Een vak uitzetten haalt het weg bij nieuwe opdrachten. Opdrachten die er al zijn houden hun vaknaam.</p>`;
}

function tekenAdminLeerlingen() {
    const scholen = lijst("scholen").filter(s => s.actief).sort((a, b) => a.naam.localeCompare(b.naam));
    const leerlingen = lijst("leerlingen").sort((a, b) =>
        (vind("scholen", a.schoolId)?.naam || "").localeCompare(vind("scholen", b.schoolId)?.naam || "") || a.naam.localeCompare(b.naam));
    return `
    <div class="kop"><div>
      <h1>Leerlingen en koppelcodes</h1>
      <p class="zacht">Elke leerling heeft een eigen code en logt daarmee in zonder wachtwoord.</p>
    </div></div>
    <details class="uitklap">
      <summary>+ Leerling toevoegen</summary>
      ${scholen.length === 0 ? `<p class="mini">Voeg eerst een school toe.</p>` : `
      <form class="formulier" data-form="leerling-nieuw">
        <div class="rij">
          <label>School<select name="schoolId" required>${scholen.map(s => `<option value="${s.id}">${esc(s.naam)}</option>`).join("")}</select></label>
          <label>Voornaam en eerste letter achternaam<input type="text" name="naam" required maxlength="60" placeholder="Sem V."></label>
          <label>Klas <span class="zacht">(mag leeg)</span><input type="text" name="klas" maxlength="40" placeholder="3 kader" list="klassenlijst"></label>
          
        </div>
        <label>Notitie voor docenten <span class="zacht">(mag leeg, zichtbaar bij de leerling)</span>
          <input type="text" name="notitie" maxlength="200" placeholder="Bijvoorbeeld: werkt in blokken van 15 minuten"></label>
        <datalist id="klassenlijst">${[...new Set(lijst("leerlingen").map(l => l.klas).filter(Boolean))].sort().map(k => `<option value="${esc(k)}">`).join("")}</datalist>
        <div><button class="knop" type="submit">Leerling toevoegen</button></div>
      </form>`}
    </details>
    <div class="tabel-omhulsel"><table class="tabel">
      <thead><tr><th>Leerling</th><th>School</th><th>Klas</th><th>Koppelcode</th><th>Opdrachten</th><th>Status</th><th></th></tr></thead>
      <tbody>
        ${leerlingen.map(l => `<tr class="${l.actief ? "" : "uit"}">
          <td><strong>${esc(l.naam)}</strong></td>
          <td>${esc(vind("scholen", l.schoolId)?.naam || "—")}</td>
          <td><form class="knoppenrij" data-form="leerling-klas" data-id="${l.id}" style="gap:.35rem;flex-wrap:nowrap">
            <input type="text" name="klas" value="${esc(l.klas || "")}" maxlength="40" placeholder="—" list="klassenlijst" style="width:96px">
            <button class="knop klein rand" type="submit">Opslaan</button>
          </form></td>
          <td><code class="code">${esc(l.koppelcode)}</code></td>
          <td class="tab-nums">${lijst("opdrachten").filter(o => o.leerlingId === l.id).length}</td>
          <td><span class="merkje ${l.actief ? "open" : "dicht"}">${l.actief ? "Actief" : "Ingetrokken"}</span></td>
          <td><div class="knoppenrij">
            <button class="knop klein rand" data-actie="leerling-code" data-id="${l.id}">Nieuwe code</button>
            <button class="knop klein ${l.actief ? "gevaar" : "rand"}" data-actie="leerling-wissel" data-id="${l.id}">${l.actief ? "Intrekken" : "Weer activeren"}</button>
          </div></td>
        </tr>`).join("") || `<tr><td colspan="7" class="zacht">Nog geen leerlingen toegevoegd.</td></tr>`}
      </tbody>
    </table></div>`;
}

function tekenAdminOpdrachten() {
    const f = S.param || { week: NU.week, jaar: NU.jaar };
    const opdrachten = lijst("opdrachten")
        .filter(o => o.werkweek === Number(f.week) && o.jaar === Number(f.jaar))
        .sort((a, b) => (vind("leerlingen", a.leerlingId)?.naam || "").localeCompare(vind("leerlingen", b.leerlingId)?.naam || ""));

    return `
    <div class="kop">
      <div>
        <h1>Opdrachten openzetten</h1>
        <p class="zacht">Leerlingen zien alleen opdrachten die op <em>open</em> staan.</p>
      </div>
      <form class="knoppenrij" data-form="weekfilter">
        <label class="mini">Week<input type="number" name="week" min="1" max="53" value="${f.week}" style="width:88px"></label>
        <label class="mini">Jaar<input type="number" name="jaar" min="2020" max="2100" value="${f.jaar}" style="width:104px"></label>
        <button class="knop klein rand" type="submit">Tonen</button>
      </form>
    </div>
    ${opdrachten.length ? `<div class="knoppenrij" style="margin-bottom:1rem">
        <button class="knop groen" data-actie="week-open" data-week="${f.week}" data-jaar="${f.jaar}">Alle opdrachten van week ${f.week} openzetten</button>
        <button class="knop rand" data-actie="week-kopie-alles" data-week="${f.week}" data-jaar="${f.jaar}">Hele week doorzetten naar week ${volgendeWeek(Number(f.week), Number(f.jaar)).week}</button>
        <button class="knop rand" data-actie="week-afronden" data-week="${f.week}" data-jaar="${f.jaar}">Hele week afronden</button>
      </div>` : ""}
    <div class="tabel-omhulsel"><table class="tabel">
      <thead><tr><th>Opdracht</th><th>Leerling</th><th>School</th><th>Vak</th><th>Bijlagen</th><th>Zichtbaar</th><th>Afgerond</th><th></th></tr></thead>
      <tbody>
        ${opdrachten.map(o => {
          const l = vind("leerlingen", o.leerlingId);
          return `<tr>
            <td><strong>${esc(o.titel)}</strong>${o.gekopieerdVan ? `<div class="mini">doorgezet uit een eerdere week</div>` : ""}</td>
            <td>${esc(l?.naam || "?")}</td>
            <td class="mini">${esc(vind("scholen", l?.schoolId)?.naam || "—")}</td>
            <td class="mini">${esc(o.vak || "—")}</td>
            <td class="tab-nums">${lijst("bijlagen").filter(b => b.opdrachtId === o.id).length}</td>
            <td><span class="merkje ${o.zichtbaar ? "open" : "dicht"}">${o.zichtbaar ? "Open" : "Dicht"}</span></td>
            <td>${o.afgerond
              ? `<span class="merkje af">Afgerond</span><div class="mini">${datumKort(o.afgerondOp)}</div>`
              : `<span class="merkje">Nog niet</span>`}</td>
            <td><div class="knoppenrij">
              <button class="knop klein ${o.zichtbaar ? "rand" : "groen"}" data-actie="opdracht-wissel" data-id="${o.id}">${o.zichtbaar ? "Sluiten" : "Openzetten"}</button>
              <button class="knop klein ${o.afgerond ? "rand" : "af"}" data-actie="opdracht-afronden" data-id="${o.id}">${o.afgerond ? "Terugzetten" : "Afvinken"}</button>
              <button class="knop klein gevaar" data-actie="opdracht-weg" data-id="${o.id}">Verwijderen</button>
            </div></td>
          </tr>`;
        }).join("") || `<tr><td colspan="8" class="zacht">Geen opdrachten in week ${f.week} van ${f.jaar}.</td></tr>`}
      </tbody>
    </table></div>`;
}

/* ------------------------------------------------------------- opbouw */
function balk() {
    if (!S.rol) return "";
    const items = {
        docent: [["docent-dashboard", "Leerlingen"]],
        leerling: [["leerling-dashboard", "Mijn opdrachten"]],
        admin: [["admin-dashboard", "Overzicht"], ["admin-agenda", "Weekagenda"], ["admin-opdrachten", "Opdrachten"],
                ["admin-leerlingen", "Leerlingen"], ["admin-scholen", "Scholen"], ["admin-vakken", "Vakken"]],
    }[S.rol];
    return `
    <header class="balk">
      <div class="merk" data-ga="home">${LOGO}<span><b>Het Kompas</b><small>Aanleverplatform onderwijs</small></span></div>
      <nav class="menu">${items.map(([s, n]) =>
        `<button data-ga="${s}" ${S.scherm === s ? 'aria-current="page"' : ""}>${n}</button>`).join("")}</nav>
      <div class="wie">
        <span class="rol-label rol-${S.rol}">${S.rol}</span>
        <span>${esc(S.ik.naam)}</span>
        <button data-actie="uitloggen">Uitloggen</button>
      </div>
    </header>`;
}

function inhoud() {
    if (!S.rol) return tekenLogin();
    switch (S.scherm) {
        case "docent-dashboard": return tekenDocentDashboard();
        case "docent-leerling":  return tekenDocentLeerling();
        case "docent-nieuw":
        case "docent-bewerk":    return tekenOpdrachtFormulier();
        case "docent-opdracht":  return tekenDocentOpdracht();
        case "leerling-dashboard": return tekenLeerlingDashboard();
        case "leerling-opdracht":  return tekenLeerlingOpdracht();
        case "admin-dashboard":  return tekenAdminDashboard();
        case "admin-agenda":     return tekenAdminAgenda();
        case "admin-scholen":    return tekenAdminScholen();
        case "admin-vakken":     return tekenAdminVakken();
        case "admin-leerlingen": return tekenAdminLeerlingen();
        case "admin-opdrachten": return tekenAdminOpdrachten();
        default: return tekenDocentDashboard();
    }
}

function teken() {
    if (!klaar) return;
    const m = S.melding;
    S.melding = null;
    el.innerHTML = `
      ${balk()}
      <main class="${S.rol ? "pagina" : ""}">
        ${m ? `<div id="meldingvak"><div class="melding ${m.soort}">${esc(m.tekst)}</div></div>` : ""}
        ${inhoud()}
      </main>
      ${S.rol ? `<footer class="voet">${LOGO}Het Kompas · De Nieuwe Koers</footer>` : ""}`;
}

/* ---------------------------------------------------------- interactie */
document.addEventListener("click", (ev) => {
    const t = ev.target.closest("[data-ga], [data-actie], [data-tab]");
    if (!t) return;

    if (t.dataset.tab) { S.tab = t.dataset.tab; teken(); return; }
    if (t.dataset.actie === "kies-school" || t.dataset.actie === "agenda-school") return;
    if (t.dataset.actie === "agenda-kies") {
        const huidig = S.param || {};
        S.param = { week: NU.week, jaar: NU.jaar, ...huidig, leerlingId: huidig.leerlingId === t.dataset.id ? "" : t.dataset.id };
        teken();
        if (window.matchMedia("(max-width: 760px)").matches) document.querySelector(".roosterpaneel")?.scrollIntoView({ block: "start" });
        return;
    }
    if (t.dataset.actie === "agenda-week") {
        const huidig = S.scherm === "admin-agenda" ? (S.param || {}) : {};
        S.param = { ...huidig, week: Number(t.dataset.week), jaar: Number(t.dataset.jaar) };
        teken(); return;
    }

    if (t.dataset.ga) {
        const s = t.dataset.ga;
        if (s === "home") { ga(S.rol === "admin" ? "admin-dashboard" : S.rol === "docent" ? "docent-dashboard" : "leerling-dashboard"); return; }
        ga(s, t.dataset.id || null);
        return;
    }

    const id = t.dataset.id;
    switch (t.dataset.actie) {
        case "uitloggen":
            api("uitloggen", {}).catch(() => {}).finally(() => {
                S.rol = null; S.ik = null; S.scherm = "login"; S.tab = "leerling";
                for (const c of Object.keys(data)) data[c] = {};
                teken();
            });
            break;
        case "bijlage-open": bijlageOpenen(id); break;
        case "bijlage-weg": wis("bijlagen", id).then(() => melden("Bijlage verwijderd.")); break;
        case "opdracht-weg": verwijderOpdracht(id); break;
        case "opdracht-wissel": {
            const o = vind("opdrachten", id);
            schrijf("opdrachten", id, { ...zonderId(o), zichtbaar: !o.zichtbaar, gewijzigd: new Date().toISOString() })
                .then(() => melden(o.zichtbaar ? "Opdracht is gesloten voor de leerling." : "Opdracht staat open voor de leerling."));
            break;
        }
        case "week-open": {
            const w = Number(t.dataset.week), j = Number(t.dataset.jaar);
            const rijen = lijst("opdrachten").filter(o => o.werkweek === w && o.jaar === j && !o.zichtbaar);
            Promise.all(rijen.map(o => schrijf("opdrachten", o.id, { ...zonderId(o), zichtbaar: true, gewijzigd: new Date().toISOString() })))
                .then(() => melden(`${rijen.length} opdracht${rijen.length === 1 ? "" : "en"} van week ${w} staan open.`));
            break;
        }
        case "school-code": {
            const s = vind("scholen", id);
            schrijf("scholen", id, { ...zonderId(s), koppelcode: nieuweCode(s.naam) })
                .then(() => melden("Nieuwe docentcode aangemaakt. De oude code werkt niet meer."));
            break;
        }
        case "school-wissel": {
            const s = vind("scholen", id);
            schrijf("scholen", id, { ...zonderId(s), actief: !s.actief }).then(() => melden("Status van de school gewijzigd."));
            break;
        }
        case "docent-vak": {
            const huidig = S.gekozenVak && S.gekozenVak.leerlingId === id ? S.gekozenVak.vakId : null;
            S.gekozenVak = { leerlingId: id, vakId: huidig === t.dataset.vak ? null : t.dataset.vak };
            S.zojuist = null;
            teken();
            if (S.gekozenVak.vakId) document.getElementById("vakdetail")?.scrollIntoView({ block: "nearest", behavior: "smooth" });
            break;
        }
        case "nieuw-voor-vak":
            ga("docent-nieuw", { id, vakId: t.dataset.vak, week: NU.week, jaar: NU.jaar });
            break;
        case "nieuw-in-week":
            ga("docent-nieuw", { id, week: Number(t.dataset.week), jaar: Number(t.dataset.jaar) });
            break;
        case "vak-wissel": {
            const vak = vind("vakken", id);
            schrijf("vakken", id, { ...zonderId(vak), actief: !vak.actief }).then(() => melden("Status van het vak gewijzigd."));
            break;
        }
        case "opdracht-kopie": kopieerOpdrachten([id]).then(n => {
            const o = vind("opdrachten", id);
            const nw = volgendeWeek(o.werkweek, o.jaar);
            melden(`De opdracht staat nu ook in ${weeklabel(nw.week, nw.jaar)}.`);
        }); break;
        case "week-kopie-leerling": {
            const w = Number(t.dataset.week), j = Number(t.dataset.jaar), nw = volgendeWeek(w, j);
            const rijen = lijst("opdrachten").filter(o => o.leerlingId === id && o.werkweek === w && o.jaar === j).map(o => o.id);
            kopieerOpdrachten(rijen).then(n => melden(n === 0
                ? `Er stond niets in ${weeklabel(w, j)} om door te zetten.`
                : `${n} opdracht${n === 1 ? "" : "en"} staan nu ook in ${weeklabel(nw.week, nw.jaar)}.`));
            break;
        }
        case "opdracht-afronden": {
            const o = vind("opdrachten", id);
            const af = !o.afgerond;
            schrijf("opdrachten", id, { ...zonderId(o), afgerond: af, afgerondOp: af ? new Date().toISOString() : "", gewijzigd: new Date().toISOString() })
                .then(() => melden(af ? "Opdracht is afgerond. De docent ziet dit meteen." : "Opdracht staat weer op onafgerond."));
            break;
        }
        case "week-afronden": {
            const w = Number(t.dataset.week), j = Number(t.dataset.jaar);
            const rijen = lijst("opdrachten").filter(o => o.werkweek === w && o.jaar === j && !o.afgerond);
            Promise.all(rijen.map(o => schrijf("opdrachten", o.id, {
                ...zonderId(o), afgerond: true, afgerondOp: new Date().toISOString(), gewijzigd: new Date().toISOString(),
            }))).then(() => melden(rijen.length === 0
                ? "Alle opdrachten van die week stonden al op afgerond."
                : `${rijen.length} opdracht${rijen.length === 1 ? "" : "en"} van week ${w} op afgerond gezet.`));
            break;
        }
        case "week-kopie-alles": {
            const w = Number(t.dataset.week), j = Number(t.dataset.jaar), nw = volgendeWeek(w, j);
            const rijen = lijst("opdrachten").filter(o => o.werkweek === w && o.jaar === j).map(o => o.id);
            kopieerOpdrachten(rijen).then(n => {
                S.melding = { tekst: n === 0 ? "Er stond niets in die week om door te zetten."
                    : `${n} opdracht${n === 1 ? "" : "en"} staan nu ook in ${weeklabel(nw.week, nw.jaar)}.`, soort: "ok" };
                ga("admin-opdrachten", { week: nw.week, jaar: nw.jaar });
            });
            break;
        }
        case "leerling-code": {
            const l = vind("leerlingen", id);
            schrijf("leerlingen", id, { ...zonderId(l), koppelcode: nieuweCode(l.naam) })
                .then(() => melden("Nieuwe koppelcode aangemaakt. De oude code werkt niet meer."));
            break;
        }
        case "leerling-wissel": {
            const l = vind("leerlingen", id);
            schrijf("leerlingen", id, { ...zonderId(l), actief: !l.actief }).then(() => melden("Status van de leerling gewijzigd."));
            break;
        }
    }
});

const zonderId = (o) => { const k = { ...o }; delete k.id; return k; };

/** Zoekt een vak op naam binnen de school (hoofdletters maken niet uit); bestaat het niet, dan wordt het aangemaakt.
    Een uitgezet vak met dezelfde naam wordt weer aangezet in plaats van dubbel aangemaakt. */
async function vakZoekOfMaak(schoolId, naam) {
    naam = String(naam || "").trim().replace(/\s+/g, " ");
    if (!naam) return null;
    const bestaand = lijst("vakken").find(v => v.schoolId === schoolId && v.naam.toLowerCase() === naam.toLowerCase());
    if (bestaand) {
        if (!bestaand.actief) await schrijf("vakken", bestaand.id, { ...zonderId(bestaand), actief: true });
        return vind("vakken", bestaand.id);
    }
    const id = nieuwId();
    await schrijf("vakken", id, { schoolId, naam, actief: true, toegevoegdDoor: S.rol === "docent" ? "docent" : "beheer", aangemaakt: new Date().toISOString() });
    return vind("vakken", id);
}

document.addEventListener("change", (ev) => {
    const sel = ev.target.closest('[data-actie="kies-school"]');
    if (sel) ga("admin-vakken", sel.value);
    const as = ev.target.closest('[data-actie="agenda-school"]');
    if (as) { S.param = { week: NU.week, jaar: NU.jaar, ...(S.param || {}), schoolId: as.value }; teken(); }
});

document.addEventListener("submit", async (ev) => {
    const f = ev.target.closest("form[data-form]");
    if (!f) return;
    ev.preventDefault();
    const v = Object.fromEntries(new FormData(f).entries());

    switch (f.dataset.form) {
        case "login-leerling": {
            try { await api("inloggen", { rol: "leerling", code: normCode(v.code) }); await laadStaat(); }
            catch (e) { return melden(e.message, "fout"); }
            ga("leerling-dashboard");
            break;
        }
        case "login-docent": {
            try { await api("inloggen", { rol: "docent", code: normCode(v.code) }); await laadStaat(); }
            catch (e) { return melden(e.message, "fout"); }
            ga("docent-dashboard");
            break;
        }
        case "vakken-leerling": {
            const l = vind("leerlingen", f.dataset.id);
            const gekozen = [...f.querySelectorAll('input[name="vakken"]:checked')].map(i => i.value);
            const extra = String(v.nieuwVak || "").split(/[\n,;]+/).map(x => x.trim()).filter(Boolean);
            for (const naam of extra) {
                const vak = await vakZoekOfMaak(l.schoolId, naam);
                if (vak && !gekozen.includes(vak.id)) gekozen.push(vak.id);
            }
            await schrijf("leerlingen", l.id, { ...zonderId(vind("leerlingen", l.id)), vakken: gekozen });
            if (extra.length) return melden(`${extra.length === 1 ? "Vak" : "Vakken"} toegevoegd en aangevinkt voor ${l.naam}.`);
            melden(gekozen.length === 0
                ? `Er staan nu geen vakken aangevinkt voor ${l.naam}.`
                : `${gekozen.length} vak${gekozen.length === 1 ? "" : "ken"} aangevinkt voor ${l.naam}.`);
            break;
        }
        case "vak-nieuw": {
            const namen = String(v.naam || "").split(/[\n,;]+/).map(x => x.trim()).filter(Boolean);
            for (const naam of namen) await schrijf("vakken", nieuwId(), { schoolId: f.dataset.school, naam, actief: true });
            melden(namen.length === 1 ? "Vak toegevoegd." : `${namen.length} vakken toegevoegd.`);
            break;
        }
        case "vak-hernoem": {
            const vak = vind("vakken", f.dataset.id);
            await schrijf("vakken", vak.id, { ...zonderId(vak), naam: String(v.naam).trim() });
            melden("Vak hernoemd. Bestaande opdrachten houden de oude naam.");
            break;
        }
        case "login-admin": {
            try { await api("inloggen", { rol: "admin", email: String(v.email).trim(), wachtwoord: String(v.wachtwoord) }); await laadStaat(); }
            catch (e) { return melden(e.message, "fout"); }
            ga("admin-dashboard");
            break;
        }
        case "opdracht": {
            const bestaand = f.dataset.id ? vind("opdrachten", f.dataset.id) : null;
            const id = bestaand ? bestaand.id : nieuwId();
            let link = String(v.link || "").trim();
            if (link && !/^https?:\/\//i.test(link)) link = "https://" + link;
            let leerling = vind("leerlingen", f.dataset.leerling);
            let vak = v.vakId && v.vakId !== "__nieuw" ? vind("vakken", v.vakId) : null;
            if (v.vakId === "__nieuw") {
                if (!String(v.nieuwVak || "").trim()) return melden("Vul de naam van het nieuwe vak in, of kies een ander vak.", "fout");
                vak = await vakZoekOfMaak(leerling.schoolId, v.nieuwVak);
                if (!(leerling.vakken || []).includes(vak.id)) {
                    await schrijf("leerlingen", leerling.id, { ...zonderId(leerling), vakken: [...(leerling.vakken || []), vak.id] });
                    leerling = vind("leerlingen", leerling.id);
                }
            }
            const magVak = vak && (leerling.vakken || []).includes(vak.id) ? vak : null;
            if (!magVak) return melden("Kies het vak van deze opdracht.", "fout");
            const body = {
                leerlingId: f.dataset.leerling,
                schoolId: leerling.schoolId,
                titel: magVak.naam,
                vakId: magVak ? magVak.id : "",
                vak: magVak ? magVak.naam : "",
                omschrijving: String(v.omschrijving || ""),
                link: link || "",
                werkweek: Number(v.werkweek) || NU.week,
                jaar: Number(v.jaar) || NU.jaar,
                zichtbaar: !!v.zichtbaar,
                afgerond: bestaand ? !!bestaand.afgerond : false,
                afgerondOp: bestaand ? (bestaand.afgerondOp || "") : "",
                aangemaakt: bestaand ? bestaand.aangemaakt : new Date().toISOString(),
                gewijzigd: bestaand ? new Date().toISOString() : "",
            };
            await schrijf("opdrachten", id, body);
            const melding = await bestandenOpslaan(f.querySelector('input[name="bijlagen"]'), id);
            if (bestaand) {
                S.melding = { tekst: "Wijzigingen opgeslagen. " + melding, soort: "ok" };
                ga("docent-opdracht", id);
            } else {
                const reeks = wekenReeks(body.werkweek, v.totWeek ? Number(v.totWeek) : null, body.jaar);
                const eersteBijlagen = lijst("bijlagen").filter(x => x.opdrachtId === id);
                for (const { week, jaar } of reeks.slice(1)) {
                    const extraId = nieuwId();
                    await schrijf("opdrachten", extraId, { ...body, werkweek: week, jaar, aangemaakt: new Date().toISOString() });
                    for (const b of eersteBijlagen) {
                        await schrijf("bijlagen", nieuwId(), { bronId: b.id, opdrachtId: extraId });
                    }
                }
                const laatste = reeks[reeks.length - 1];
                S.zojuist = id;
                S.gekozenVak = { leerlingId: leerling.id, vakId: body.vakId };
                S.melding = {
                    tekst: `"${body.titel}" staat klaar ` + (reeks.length === 1
                        ? `in ${weeklabel(body.werkweek, body.jaar)}`
                        : `in ${reeks.length} weken: week ${body.werkweek} t/m week ${laatste.week} (${laatste.jaar})`)
                        + ` voor ${leerling.naam}. ` + melding,
                    soort: "ok",
                };
                ga("docent-leerling", leerling.id, "vakdetail");
            }
            break;
        }
        case "opmerking": {
            const tekst = String(v.tekst || "").trim();
            if (!tekst) return;
            await schrijf("opmerkingen", nieuwId(), {
                opdrachtId: f.dataset.id,
                auteur: String(v.auteur || "").trim() || S.ik.naam,
                tekst, aangemaakt: new Date().toISOString(),
            });
            melden("Opmerking geplaatst.");
            break;
        }
        case "school-nieuw": {
            const naam = String(v.naam).trim();
            await schrijf("scholen", nieuwId(), { naam, plaats: String(v.plaats || "").trim(), koppelcode: nieuweCode(naam), actief: true });
            melden("School toegevoegd.");
            break;
        }
        case "leerling-nieuw": {
            const naam = String(v.naam).trim().replace(/\s+/g, " ");
            const klasNieuw = String(v.klas || "").trim().toLowerCase();
            const zelfde = lijst("leerlingen").filter(l => l.schoolId === v.schoolId && l.naam.trim().toLowerCase() === naam.toLowerCase());
            if (zelfde.some(l => String(l.klas || "").trim().toLowerCase() === klasNieuw)) {
                return melden(`Bij deze school staat al een leerling "${naam}"${klasNieuw ? " in dezelfde klas" : ""}. Voeg een extra letter van de achternaam toe, bijvoorbeeld "Sara Ja.".`, "fout");
            }
            if (zelfde.length) S.dubbeleNaam = naam;
            await schrijf("leerlingen", nieuwId(), {
                schoolId: v.schoolId, naam,
                
                klas: String(v.klas || "").trim(),
                koppelcode: nieuweCode(naam), notitie: String(v.notitie || "").trim(), vakken: [], actief: true,
            });
            const dubbel = S.dubbeleNaam; S.dubbeleNaam = null;
            melden(dubbel
                ? `Leerling toegevoegd. Let op: er is op deze school nog een "${dubbel}" in een andere klas. Kijk bij het klaarzetten van werk goed naar de klas.`
                : "Leerling toegevoegd. De koppelcode staat in de lijst.");
            break;
        }
        case "leerling-klas": {
            const l = vind("leerlingen", f.dataset.id);
            await schrijf("leerlingen", l.id, { ...zonderId(l), klas: String(v.klas || "").trim() });
            melden(`Klas van ${l.naam} opgeslagen.`);
            break;
        }
        case "weekfilter": {
            ga("admin-opdrachten", { week: Number(v.week), jaar: Number(v.jaar) });
            break;
        }
    }
});

async function bestandenOpslaan(input, opdrachtId) {
    const files = input && input.files ? [...input.files] : [];
    if (!files.length) return "";
    let opgeslagen = 0;
    const fouten = [];
    for (const file of files) {
        if (file.size > MAX_BESTAND_MB * 1048576) { fouten.push(`"${file.name}" is groter dan ${MAX_BESTAND_MB} MB`); continue; }
        const fd = new FormData();
        fd.append("opdrachtId", opdrachtId);
        fd.append("bestand", file, file.name);
        try { await api("uploaden", fd); opgeslagen++; }
        catch (e) { fouten.push(`"${file.name}": ${e.message}`); }
    }
    try { await laadStaat(); } catch (e) { /* stil */ }
    let m = opgeslagen ? `${opgeslagen} bestand${opgeslagen === 1 ? "" : "en"} toegevoegd.` : "";
    if (fouten.length) m += " Niet gelukt: " + fouten.join("; ") + ".";
    return m;
}

async function bijlageOpenen(id) {
    if (!vind("bijlagen", id)) return;
    try {
        const { url } = await api("download", { id });
        if (url) window.location.href = url;
    } catch (e) { melden(e.message || "Het bestand kon niet worden geopend.", "fout"); }
}

/** Zet opdrachten (met bijlagen) opnieuw klaar, een week later. */
async function kopieerOpdrachten(ids) {
    let aantal = 0;
    for (const id of ids) {
        const o = vind("opdrachten", id);
        if (!o) continue;
        const nw = volgendeWeek(Number(o.werkweek), Number(o.jaar));
        const nieuw = nieuwId();
        await schrijf("opdrachten", nieuw, {
            ...zonderId(o), werkweek: nw.week, jaar: nw.jaar,
            afgerond: false, afgerondOp: "",
            gekopieerdVan: o.id, aangemaakt: new Date().toISOString(), gewijzigd: "",
        });
        for (const b of lijst("bijlagen").filter(x => x.opdrachtId === o.id)) {
            await schrijf("bijlagen", nieuwId(), { bronId: b.id, opdrachtId: nieuw });
        }
        aantal++;
    }
    return aantal;
}

async function verwijderOpdracht(id) {
    const o = vind("opdrachten", id);
    if (!o || !confirm("Deze opdracht en alle bijlagen definitief verwijderen?")) return;
    const leerlingId = o.leerlingId;
    for (const b of lijst("bijlagen").filter(x => x.opdrachtId === id)) await wis("bijlagen", b.id);
    for (const m of lijst("opmerkingen").filter(x => x.opdrachtId === id)) await wis("opmerkingen", m.id);
    await wis("opdrachten", id);
    S.melding = { tekst: "Opdracht verwijderd.", soort: "ok" };
    ga(S.rol === "admin" ? "admin-opdrachten" : "docent-leerling", S.rol === "admin" ? null : leerlingId);
}

/* -------------------------------------------------------------- start */
(async function start() {
    try {
        await laadStaat();
    } catch (e) {
        klaar = true;
        el.innerHTML = `<div class="pagina"><div class="melding fout">De server is nu niet bereikbaar. Herlaad de pagina over een paar minuten.</div></div>`;
        return;
    }
    klaar = true;
    S.scherm = S.rol === "admin" ? "admin-dashboard" : S.rol === "docent" ? "docent-dashboard" : S.rol === "leerling" ? "leerling-dashboard" : "login";
    teken();
})();
